        }
        Order order = found.get();
        if (order.status() != OrderStatus.PAID) {
            return Result.failure(
                    ErrorCode.INVALID_STATE,
                    "Only paid orders can be shipped, but order " + order.id() + " is " + order.status());
        }
        order.markShipped();
        orders.save(order);
        return Result.ok(order);
