package shop;

public enum ErrorCode {
    INVALID_INPUT,
    NOT_FOUND,
    ALREADY_EXISTS,
    INVALID_STATE
}
package shop;

/** Wires every command to its handler. */
public final class OrderServices {

    private OrderServices() {}

    public static CommandBus createBus(OrderRepository orders) {
        CommandBus bus = new CommandBus();
        bus.register(PlaceOrder.class, new PlaceOrderHandler(orders));
        bus.register(PayOrder.class, new PayOrderHandler(orders));
        bus.register(ShipOrder.class, new ShipOrderHandler(orders));
        bus.register(DeliverOrder.class, new DeliverOrderHandler(orders));
        bus.register(CancelOrder.class, new CancelOrderHandler(orders));
        return bus;
    }
}
package shop;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/** Collects the problems of a command's input so that a handler can reject it with one failed result. */
public final class Validator {
    private static final int MONEY_SCALE = 2;

    private final List<String> problems = new ArrayList<>();

    public Validator requireText(String field, String value) {
        if (value == null || value.isBlank()) {
            problems.add(field + " must not be blank");
        }
        return this;
    }

    public Validator requireMoney(String field, BigDecimal value) {
        if (value == null) {
            problems.add(field + " is required");
        } else if (value.signum() <= 0) {
            problems.add(field + " must be greater than zero");
        } else if (value.stripTrailingZeros().scale() > MONEY_SCALE) {
            problems.add(field + " must have at most two decimal places");
        }
        return this;
    }

    public boolean isValid() {
        return problems.isEmpty();
    }

    public <T> Result<T> failure() {
        return Result.failure(ErrorCode.INVALID_INPUT, String.join("; ", problems));
    }
}
package shop;

import java.util.Objects;

/** The outcome of a command: the updated value, or a failure that says why the command was rejected. */
public final class Result<T> {

    public record Failure(ErrorCode code, String message) {}

    private final T value;
    private final Failure failure;

    private Result(T value, Failure failure) {
        this.value = value;
        this.failure = failure;
    }

    public static <T> Result<T> ok(T value) {
        return new Result<>(Objects.requireNonNull(value), null);
    }

    public static <T> Result<T> failure(ErrorCode code, String message) {
        return new Result<>(null, new Failure(code, message));
    }

    public boolean isOk() {
        return failure == null;
    }

    public T value() {
        if (failure != null) {
            throw new IllegalStateException("Result failed: " + failure.message());
        }
        return value;
    }

    public Failure error() {
        if (failure == null) {
            throw new IllegalStateException("Result is ok");
        }
        return failure;
    }
}
package shop;

import java.util.HashMap;
import java.util.Map;

public final class CommandBus {
    private final Map<Class<?>, CommandHandler<?>> handlers = new HashMap<>();

    public <C> void register(Class<C> commandType, CommandHandler<C> handler) {
        if (handlers.putIfAbsent(commandType, handler) != null) {
            throw new IllegalStateException("Handler already registered for " + commandType.getSimpleName());
        }
    }

    @SuppressWarnings("unchecked")
    public <C> Result<Order> dispatch(C command) {
        CommandHandler<C> handler = (CommandHandler<C>) handlers.get(command.getClass());
        if (handler == null) {
            return Result.failure(
                    ErrorCode.INVALID_INPUT, "No handler registered for " + command.getClass().getSimpleName());
        }
        return handler.handle(command);
    }
}
package shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class PayOrderHandlerTest {
    private final OrderRepository orders = new InMemoryOrderRepository();
    private final CommandBus bus = OrderServices.createBus(orders);

    @BeforeEach
    void placeOrder() {
        bus.dispatch(new PlaceOrder("o-1", "c-1", new BigDecimal("100.00")));
    }

    @Test
    void recordsTheAmountActuallyPaid() {
        Result<Order> result = bus.dispatch(new PayOrder("o-1", new BigDecimal("80.00")));

        assertTrue(result.isOk());
        Order stored = orders.find("o-1").orElseThrow();
        assertEquals(OrderStatus.PAID, stored.status());
        assertEquals(0, new BigDecimal("80.00").compareTo(stored.amountPaid()));
    }

    @Test
    void rejectsMoreThanTheTotal() {
        Result<Order> result = bus.dispatch(new PayOrder("o-1", new BigDecimal("100.01")));

        assertFalse(result.isOk());
        assertEquals(ErrorCode.INVALID_INPUT, result.error().code());
    }

    @Test
    void rejectsAnOrderThatIsAlreadyPaid() {
        bus.dispatch(new PayOrder("o-1", new BigDecimal("100.00")));

        Result<Order> result = bus.dispatch(new PayOrder("o-1", new BigDecimal("100.00")));

        assertFalse(result.isOk());
        assertEquals(ErrorCode.INVALID_STATE, result.error().code());
    }

    @Test
    void reportsAnUnknownOrder() {
        Result<Order> result = bus.dispatch(new PayOrder("missing", new BigDecimal("10.00")));

        assertEquals(ErrorCode.NOT_FOUND, result.error().code());
    }
}
# Order service

A small order service built around commands. Every command is a record, every command has exactly one handler
class, and handlers talk to orders through an `OrderRepository`. Handlers report expected problems (bad input,
unknown order, wrong status) as a failed `Result`; they do not throw.

## Commands

| Command        | Handler               | Moves the order from              |
|----------------|-----------------------|-----------------------------------|
| `PlaceOrder`   | `PlaceOrderHandler`   | (new) to `PLACED`                 |
| `PayOrder`     | `PayOrderHandler`     | `PLACED` to `PAID`                |
| `ShipOrder`    | `ShipOrderHandler`    | `PAID` to `SHIPPED`               |
| `DeliverOrder` | `DeliverOrderHandler` | `SHIPPED` to `DELIVERED`          |
| `CancelOrder`  | `CancelOrderHandler`  | `PLACED` or `PAID` to `CANCELLED` |

All handlers are registered in `OrderServices.createBus`. Commands are sent through `CommandBus.dispatch`.

An order's amount paid can be lower than its total, for example when a voucher covered part of it. Money is
`BigDecimal` with at most two decimal places.

## Tests

`java tools/RunTests.java` compiles `src/main` and `src/test` into `build/` and runs all JUnit 5 tests with the
console launcher in `lib/`. It needs a JDK (17 or newer).
